import math

def prime_order(a, n):
    """Calculates the multiplicative order of a modulo n."""
    if math.gcd(a, n) != 1:
        return 0 # Should not happen based on problem constraints

    phi_n = n - 1

    # Find prime factors of phi_n
    factors = set()
    d = 2
    temp = phi_n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)

    # Check powers
    order = phi_n
    for p in factors:
        power = phi_n // p
        while math.gcd(a**power - 1, n) == 1: # Check if a^(phi_n/p) == 1 mod n
            order = power
            power //= p

    # A more robust way to find the order:
    current_order = phi_n
    for p in factors:
        while current_order % p == 0:
            exponent = current_order // p
            if pow(a, exponent, n) == 1:
                current_order = exponent
            else:
                break
    return current_order

def calculate_N(p):
    """Calculates N(p), the number of cycles for x -> 3x mod p."""
    if p == 2:
        return 1
    if p == 3:
        return None # Should be excluded

    # We rely on gcd(3, p) = 1 since p != 3
    try:
        L = prime_order(3, p)
    except ValueError:
        # Should not happen if p is prime and p!=3
        return None

    if L == 0: # Should not happen
        return None

    return (p - 1) // L

