import itertools

def generate_products(primes_list, limit):
    products = set()

    # Iterate through combinations of size k
    for k in range(1, len(primes_list) + 1):
        for combo in itertools.combinations(primes_list, k):
            m = 1
            for p in combo:
                m *= p

            if m <= limit:
                products.add(m)
            elif k > 1: # If current product exceeds limit, larger combos will too (since primes are positive)
                pass
    return sorted(list(products), reverse=True)

