    """Calculates the multiplicative order of base modulo modulus."""
    phi = modulus - 1
    factors = []
    n = phi
    i = 2
    while i * i <= n:
        if n % i == 0:
            factors.append(i)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        factors.append(n)

    order = phi
    for p in factors:
        exponent = order // p
        # Check if order / p is still a power of base
        if pow(base, exponent, modulus) == 1:
